        for (i = 0; i < N; i++) coarse[i] = coarseOf(x, i);
        // the closest K: the K-th smallest distance from a sorted copy, then only those sorted by index
        var K = Math.min(N, k), res = [], seen = {}, lim = Float32Array.from(coarse).sort()[K - 1], take = [];
        for (i = 0; i < N; i++) if (coarse[i] <= lim) take.push(i);
